       AND (
           NEW.status IS DISTINCT FROM 'deleting'
           OR (to_jsonb(NEW) - 'deletion_token' - 'updated_at')
              IS DISTINCT FROM
              (to_jsonb(OLD) - 'deletion_token' - 'updated_at')
       ) THEN
        RETURN NULL;
    END IF;
