-- Product objects present in the historical Plue schema before adoption.
-- Retain the gateway proof behind each reserved repository CI commit status.
-- A request id is idempotent only within the reviewed CI registration.
CREATE TABLE repository_ci_check_receipts (
    id               bigserial PRIMARY KEY,
    repository_id    bigint NOT NULL REFERENCES repositories(id) ON DELETE CASCADE,
    registration_id  uuid   NOT NULL REFERENCES repository_job_registrations(id) ON DELETE CASCADE,
    revision         bigint NOT NULL,
    digest           text   NOT NULL,
    execution_digest text   NOT NULL,
    workspace_id     uuid   NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    run_id           text   NOT NULL,
    execution_id     text   NOT NULL,
    commit_sha       text   NOT NULL,
    change_id        text   NOT NULL,
    base_commit_sha  text   NOT NULL,
    checks           jsonb  NOT NULL,
    context          text   NOT NULL,
    commit_status_id bigint NOT NULL REFERENCES commit_statuses(id) ON DELETE CASCADE,
    request_id       text   NOT NULL,
    created_at       timestamptz NOT NULL DEFAULT now(),
    UNIQUE (registration_id, request_id)
);

CREATE INDEX idx_repository_ci_check_receipts_repo_commit
    ON repository_ci_check_receipts (repository_id, commit_sha);

-- Human approval provenance for reviewed repository flow plans. The service
-- supplies approved_by from the authenticated session and approved_at from
-- PostgreSQL; neither field is accepted from a host, flow, or model.
CREATE TABLE repository_job_approvals (
    repository_id bigint NOT NULL REFERENCES repositories(id) ON DELETE CASCADE,
    job           text   NOT NULL,
    plan_digest   text   NOT NULL CHECK (plan_digest ~ '^[a-f0-9]{64}$'),
    plan_id       text   NOT NULL,
    flow_id       text   NOT NULL,
    envelope      jsonb  NOT NULL,
    approved_by   bigint NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    approved_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (repository_id, job, plan_digest)
);

-- A staged delete or ownership move has one durable receipt across embedded
-- and hosted repository services. storage_route_key is an opaque trusted route
-- handle: "static" addresses the embedded service, while a hosted adapter may
-- resolve it through its private placement catalog. It is never a URL or a
-- column on the product repository row.
CREATE TABLE public.repository_storage_operations (
    repository_id bigint PRIMARY KEY,
    operation_type varchar(16) NOT NULL CHECK (operation_type IN ('delete', 'move')),
    token varchar(64) NOT NULL UNIQUE CHECK (token ~ '^[0-9a-f]{64}$'),
    storage_route_key text NOT NULL CONSTRAINT repository_storage_route_key_nonempty CHECK (btrim(storage_route_key) <> ''),
    source_owner varchar(255) NOT NULL CHECK (btrim(source_owner) <> ''),
    source_repo varchar(255) NOT NULL CHECK (btrim(source_repo) <> ''),
    source_user_id bigint,
    source_org_id bigint,
    target_owner varchar(255),
    target_repo varchar(255),
    target_user_id bigint,
    target_org_id bigint,
    claim_token varchar(64),
    claimed_at timestamptz,
    attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    last_error text,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CHECK (num_nonnulls(source_user_id, source_org_id) = 1),
    CHECK (
        (operation_type = 'delete' AND target_owner IS NULL AND target_repo IS NULL
            AND target_user_id IS NULL AND target_org_id IS NULL)
        OR
        (operation_type = 'move' AND target_owner IS NOT NULL AND target_repo IS NOT NULL
            AND btrim(target_owner) <> '' AND btrim(target_repo) <> ''
            AND num_nonnulls(target_user_id, target_org_id) = 1)
    ),
    CHECK ((claim_token IS NULL AND claimed_at IS NULL)
        OR (claim_token IS NOT NULL AND claimed_at IS NOT NULL))
);
CREATE INDEX idx_repository_storage_operations_reconcile
    ON public.repository_storage_operations(created_at, claimed_at, repository_id);


CREATE UNIQUE INDEX idx_provider_connections_web_request
    ON public.provider_connections (user_id, label) WHERE owner_type = 'user' AND label LIKE 'web-%';

-- Current product flow registrations are part of the baseline on fresh installs.
ALTER TABLE public.repository_job_registrations DROP CONSTRAINT repository_job_registrations_job_check;
ALTER TABLE public.repository_job_registrations ADD CONSTRAINT repository_job_registrations_job_check
    CHECK (job IN ('issues','review','ci','feature','chores') OR job ~ '^flow:[a-z0-9][a-z0-9-]{0,63}$');
ALTER TABLE public.repository_job_registrations ADD CONSTRAINT repository_job_registrations_flow_mode_check
    CHECK (job !~ '^flow:' OR mode = 'enabled');
-- END product/migrations/0001_product_baseline.sql

-- BEGIN product/migrations/0002_import_publication.sql
-- A local import's durable reservation is its import_jobs row. These fields
-- let a restarted worker publish an already-pushed mirror without asking
-- GitHub again or depending on the cluster provisioning journal.
ALTER TABLE public.import_jobs
    ADD COLUMN default_bookmark text NOT NULL DEFAULT '',
    ADD COLUMN publish_ready boolean NOT NULL DEFAULT false;
-- END product/migrations/0002_import_publication.sql

-- BEGIN product/migrations/0003_repository_creation_jobs.sql
-- A repository create or fork reserves its identity before touching the jj
-- store. The operation survives a process crash until storage, metadata, and
-- the staged repository journal have all settled.
CREATE TABLE public.repository_creation_jobs (
    repository_id bigint PRIMARY KEY,
    token text NOT NULL UNIQUE CHECK (token ~ '^[0-9a-f]{64}$'),
    operation_type text NOT NULL CHECK (operation_type IN ('init', 'fork')),
    actor_id bigint NOT NULL REFERENCES public.users(id) ON DELETE RESTRICT,
    user_id bigint REFERENCES public.users(id) ON DELETE RESTRICT,
    org_id bigint REFERENCES public.organizations(id) ON DELETE RESTRICT,
    owner_name text NOT NULL,
    name varchar(255) NOT NULL,
    lower_name varchar(255) NOT NULL,
    description text NOT NULL DEFAULT '',
    is_public boolean NOT NULL,
    default_bookmark varchar(255) NOT NULL,
    auto_init boolean NOT NULL DEFAULT false,
    source_repository_id bigint REFERENCES public.repositories(id) ON DELETE RESTRICT,
    source_owner text,
    source_repo text,
    attempts integer NOT NULL DEFAULT 0,
    last_error text,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT repository_creation_owner CHECK (num_nonnulls(user_id, org_id) = 1),
    CONSTRAINT repository_creation_source CHECK (
        (operation_type = 'init' AND source_repository_id IS NULL AND source_owner IS NULL AND source_repo IS NULL)
        OR (operation_type = 'fork' AND user_id IS NOT NULL AND source_repository_id IS NOT NULL
            AND source_owner IS NOT NULL AND source_repo IS NOT NULL)
    ),
    CONSTRAINT repository_creation_name CHECK (lower_name = lower(name))
);
CREATE UNIQUE INDEX repository_creation_user_name
    ON public.repository_creation_jobs(user_id, lower_name) WHERE user_id IS NOT NULL;
CREATE UNIQUE INDEX repository_creation_org_name
    ON public.repository_creation_jobs(org_id, lower_name) WHERE org_id IS NOT NULL;

-- Use the same namespace lock for reservations and all repository inserts or
-- owner/name changes. Other writers cannot slip a row between the reservation
-- check and its commit, and cannot publish over a pending staged repository.
CREATE FUNCTION public.smithers_product_repository_namespace_key(
    p_user_id bigint, p_org_id bigint, p_lower_name text
) RETURNS bigint LANGUAGE sql IMMUTABLE AS $$
    SELECT hashtextextended(
        CASE WHEN p_user_id IS NOT NULL THEN 'user:' || p_user_id::text
             ELSE 'org:' || p_org_id::text END || ':' || lower(p_lower_name), 0)
$$;

CREATE FUNCTION public.smithers_product_repository_creation_fence()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE pending public.repository_creation_jobs%ROWTYPE;
BEGIN
    IF TG_OP = 'DELETE' THEN
        IF EXISTS (SELECT 1 FROM public.repository_creation_jobs WHERE repository_id = OLD.id) THEN
            RAISE EXCEPTION 'repository creation has not finalized' USING ERRCODE = '23503';
        END IF;
        RETURN OLD;
    END IF;
    IF TG_OP = 'UPDATE' AND
       (OLD.user_id IS DISTINCT FROM NEW.user_id OR OLD.org_id IS DISTINCT FROM NEW.org_id
        OR OLD.lower_name IS DISTINCT FROM NEW.lower_name) AND
       EXISTS (SELECT 1 FROM public.repository_creation_jobs WHERE repository_id = OLD.id) THEN
        RAISE EXCEPTION 'repository creation has not finalized' USING ERRCODE = '23503';
    END IF;
    PERFORM pg_advisory_xact_lock(public.smithers_product_repository_namespace_key(
        NEW.user_id, NEW.org_id, NEW.lower_name));
    SELECT * INTO pending FROM public.repository_creation_jobs
      WHERE lower_name = NEW.lower_name
        AND ((NEW.user_id IS NOT NULL AND user_id = NEW.user_id)
          OR (NEW.org_id IS NOT NULL AND org_id = NEW.org_id));
    IF FOUND AND (TG_OP = 'INSERT' OR NEW.id <> pending.repository_id)
       AND current_setting('smithers.product_repository_creation_token', true) IS DISTINCT FROM pending.token THEN
        RAISE EXCEPTION 'repository namespace is reserved for creation' USING ERRCODE = '23505';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER repository_creation_fence
BEFORE INSERT OR UPDATE OF user_id, org_id, lower_name ON public.repositories
FOR EACH ROW EXECUTE FUNCTION public.smithers_product_repository_creation_fence();

CREATE TRIGGER repository_creation_delete_fence
BEFORE DELETE ON public.repositories
FOR EACH ROW EXECUTE FUNCTION public.smithers_product_repository_creation_fence();
-- END product/migrations/0003_repository_creation_jobs.sql

-- BEGIN product/migrations/0004_single_owner_identity.sql
-- Exactly one trusted owner may claim a self-hosted installation. The
-- singleton constraint is the concurrency boundary for first-run bootstrap.
CREATE TABLE self_host_owners (
    singleton       BOOLEAN PRIMARY KEY DEFAULT TRUE CHECK (singleton),
    user_id         BIGINT NOT NULL UNIQUE REFERENCES users(id) ON DELETE RESTRICT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE local_credentials (
    user_id              BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    password_hash        TEXT NOT NULL,
    password_changed_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    created_at           TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at           TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
-- END product/migrations/0004_single_owner_identity.sql

-- BEGIN product/migrations/0005_durable_product_jobs.sql
-- Shared product-operation admission and delivery. These rows queue external
-- effects; they do not describe a Flow graph or replace the canonical
-- TypeScript Flow/Control journal.
CREATE TABLE product_job_streams (
    tenant_id TEXT NOT NULL,
    principal_id TEXT NOT NULL,
    head BIGINT NOT NULL DEFAULT 0 CHECK (head >= 0),
    retention_floor BIGINT NOT NULL DEFAULT 1 CHECK (retention_floor > 0),
    PRIMARY KEY (tenant_id, principal_id),
    CHECK (tenant_id <> '' AND principal_id <> ''),
    CHECK (retention_floor <= head + 1)
);

CREATE TABLE product_job_requests (
    id UUID PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    principal_id TEXT NOT NULL,
    operation TEXT NOT NULL,
    request_id TEXT NOT NULL,
    payload_fingerprint BYTEA NOT NULL CHECK (octet_length(payload_fingerprint) = 32),
    payload JSONB NOT NULL,
    authorization_context JSONB NOT NULL CHECK (jsonb_typeof(authorization_context) = 'object'),
    state TEXT NOT NULL CHECK (state IN (
        'accepted', 'dispatching', 'running', 'waiting',
        'completed', 'failed', 'cancelled', 'uncertain'
    )),
    request_receipt JSONB NOT NULL CHECK (jsonb_typeof(request_receipt) = 'object'),
    terminal_receipt JSONB CHECK (terminal_receipt IS NULL OR jsonb_typeof(terminal_receipt) = 'object'),
    cancellation_requested BOOLEAN NOT NULL DEFAULT FALSE,
    cancellation_requested_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
    UNIQUE (tenant_id, principal_id, operation, request_id),
    UNIQUE (id, tenant_id, principal_id),
    CHECK (tenant_id <> '' AND principal_id <> '' AND operation <> '' AND request_id <> ''),
    CHECK ((cancellation_requested AND cancellation_requested_at IS NOT NULL)
        OR (NOT cancellation_requested AND cancellation_requested_at IS NULL)),
    CHECK ((state IN ('completed', 'failed', 'cancelled', 'uncertain')) = (terminal_receipt IS NOT NULL))
);

CREATE INDEX product_job_requests_owner_created
    ON product_job_requests (tenant_id, principal_id, created_at, id);

CREATE TABLE product_job_dispatches (
    operation_id UUID PRIMARY KEY REFERENCES product_job_requests(id) ON DELETE CASCADE,
    status TEXT NOT NULL DEFAULT 'ready' CHECK (status IN ('ready', 'claimed', 'done', 'stopped')),
    effect_policy TEXT NOT NULL CHECK (effect_policy IN ('idempotent', 'reconcile', 'unsafe')),
    effect_key TEXT NOT NULL,
    attempt INTEGER NOT NULL DEFAULT 0 CHECK (attempt >= 0),
    external_attempt INTEGER NOT NULL DEFAULT 1 CHECK (external_attempt > 0),
    generation BIGINT NOT NULL DEFAULT 0 CHECK (generation >= 0),
    claim_token UUID,
    worker_id TEXT,
    claimed_at TIMESTAMPTZ,
    lease_expires_at TIMESTAMPTZ,
    external_started_at TIMESTAMPTZ,
    external_receipt JSONB CHECK (external_receipt IS NULL OR jsonb_typeof(external_receipt) = 'object'),
    reconcile_required BOOLEAN NOT NULL DEFAULT FALSE,
    next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
    last_error TEXT NOT NULL DEFAULT '',
    updated_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
    CHECK (effect_key <> ''),
    CHECK (
        (status = 'claimed' AND claim_token IS NOT NULL AND worker_id IS NOT NULL
            AND claimed_at IS NOT NULL AND lease_expires_at IS NOT NULL)
        OR
        (status <> 'claimed' AND claim_token IS NULL AND worker_id IS NULL
            AND claimed_at IS NULL AND lease_expires_at IS NULL)
    )
);

CREATE INDEX product_job_dispatches_ready
    ON product_job_dispatches (next_attempt_at, operation_id)
    WHERE status = 'ready';
CREATE INDEX product_job_dispatches_expired
    ON product_job_dispatches (lease_expires_at, operation_id)
    WHERE status = 'claimed';

CREATE TABLE product_job_events (
    tenant_id TEXT NOT NULL,
    principal_id TEXT NOT NULL,
    sequence BIGINT NOT NULL CHECK (sequence > 0),
    event_id UUID NOT NULL UNIQUE,
    operation_id UUID NOT NULL,
    event_type TEXT NOT NULL,
    state TEXT NOT NULL,
    data JSONB NOT NULL CHECK (jsonb_typeof(data) = 'object'),
    recorded_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
    PRIMARY KEY (tenant_id, principal_id, sequence),
    FOREIGN KEY (tenant_id, principal_id)
        REFERENCES product_job_streams(tenant_id, principal_id) ON DELETE CASCADE,
    FOREIGN KEY (operation_id, tenant_id, principal_id)
        REFERENCES product_job_requests(id, tenant_id, principal_id) ON DELETE RESTRICT,
    CHECK (tenant_id <> '' AND principal_id <> '' AND event_type <> '' AND state <> '')
);

CREATE INDEX product_job_events_operation
    ON product_job_events (operation_id, sequence);
-- END product/migrations/0005_durable_product_jobs.sql

-- BEGIN product/migrations/0006_repository_storage_fences.sql
-- Every metadata mutation while a storage journal exists is fenced by its
-- token. A direct delete or owner transfer cannot bypass staged jj storage.
CREATE FUNCTION public.smithers_product_repository_storage_fence()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
    pending public.repository_storage_operations%ROWTYPE;
    authorized_token text := nullif(current_setting('smithers.repository_storage_operation_token', true), '');
BEGIN
    SELECT * INTO pending FROM public.repository_storage_operations WHERE repository_id = OLD.id;
    IF TG_OP = 'DELETE' THEN
        IF NOT FOUND OR pending.operation_type <> 'delete'
            OR pending.token IS DISTINCT FROM authorized_token
            OR OLD.user_id IS DISTINCT FROM pending.source_user_id
            OR OLD.org_id IS DISTINCT FROM pending.source_org_id
            OR OLD.name IS DISTINCT FROM pending.source_repo
            OR OLD.lower_name IS DISTINCT FROM lower(pending.source_repo) THEN
            RAISE EXCEPTION 'repository deletion requires its durable storage journal' USING ERRCODE = '55006';
        END IF;
        RETURN OLD;
    END IF;
    IF NEW.name IS DISTINCT FROM OLD.name OR NEW.lower_name IS DISTINCT FROM OLD.lower_name THEN
        RAISE EXCEPTION 'repository storage namespace is immutable' USING ERRCODE = '0A000';
    END IF;
    IF NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.org_id IS DISTINCT FROM OLD.org_id THEN
        IF NOT FOUND OR pending.operation_type <> 'move'
            OR pending.token IS DISTINCT FROM authorized_token
            OR OLD.user_id IS DISTINCT FROM pending.source_user_id
            OR OLD.org_id IS DISTINCT FROM pending.source_org_id
            OR OLD.name IS DISTINCT FROM pending.source_repo
            OR NEW.user_id IS DISTINCT FROM pending.target_user_id
            OR NEW.org_id IS DISTINCT FROM pending.target_org_id
            OR NEW.name IS DISTINCT FROM pending.target_repo THEN
            RAISE EXCEPTION 'repository transfer requires its durable storage journal' USING ERRCODE = '55006';
        END IF;
        RETURN NEW;
    END IF;
    IF FOUND THEN
        RAISE EXCEPTION 'repository storage operation is unresolved' USING ERRCODE = '55006';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER repository_storage_fence
BEFORE UPDATE OR DELETE ON public.repositories
FOR EACH ROW EXECUTE FUNCTION public.smithers_product_repository_storage_fence();

-- Owner FK cascades must not erase repository metadata before its jj storage
-- has been staged and its durable receipt committed.
CREATE FUNCTION public.smithers_product_repository_owner_delete_fence()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF TG_TABLE_NAME = 'users' AND EXISTS (SELECT 1 FROM public.repositories WHERE user_id = OLD.id) THEN
        RAISE EXCEPTION 'user still owns repositories' USING ERRCODE = '55006';
    END IF;
    IF TG_TABLE_NAME = 'organizations' AND EXISTS (SELECT 1 FROM public.repositories WHERE org_id = OLD.id) THEN
        RAISE EXCEPTION 'organization still owns repositories' USING ERRCODE = '55006';
    END IF;
    RETURN OLD;
END;
$$;
CREATE TRIGGER repository_user_delete_fence
BEFORE DELETE ON public.users FOR EACH ROW
EXECUTE FUNCTION public.smithers_product_repository_owner_delete_fence();
CREATE TRIGGER repository_org_delete_fence
BEFORE DELETE ON public.organizations FOR EACH ROW
EXECUTE FUNCTION public.smithers_product_repository_owner_delete_fence();
-- END product/migrations/0006_repository_storage_fences.sql

-- BEGIN product/migrations/0007_chat_turns.sql
CREATE TABLE chat_turns (
  id text PRIMARY KEY,
  repository_id bigint NOT NULL DEFAULT 0,
  user_id bigint NOT NULL,
  run_id text NOT NULL,
  leg_id text NOT NULL,
  request_payload jsonb,
  request_hash text NOT NULL,
  owner_hash text,
  access_hash text NOT NULL,
  writer_hash text,
  acceptance jsonb,
  acceptance_hash text,
  accepted_at_ms bigint,
  head_batch bigint NOT NULL DEFAULT 0 CHECK (head_batch >= 0),
  head_position bigint NOT NULL DEFAULT 0 CHECK (head_position >= 0),
  cursor_hash text,
  head_hash text,
  output_bytes bigint NOT NULL DEFAULT 0 CHECK (output_bytes >= 0),
  terminal boolean NOT NULL DEFAULT false,
  state text NOT NULL CHECK (state IN ('accepted','running','completed','failed','cancelled','uncertain','retired')),
  producer_generation bigint NOT NULL DEFAULT 0 CHECK (producer_generation >= 0),
  producer_token_hash text,
  producer_lease_expires_at timestamptz,
  producer_started_at timestamptz,
  cancel_requested_at timestamptz,
  retirement jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (user_id, run_id, leg_id)
);

CREATE INDEX chat_turns_recovery_idx
  ON chat_turns(state, producer_lease_expires_at, created_at)
  WHERE state IN ('accepted','running');
CREATE INDEX chat_turns_run_idx
  ON chat_turns(user_id, run_id, created_at);

CREATE TABLE chat_turn_batches (
  turn_id text NOT NULL REFERENCES chat_turns(id) ON DELETE CASCADE,
  batch_number bigint NOT NULL CHECK (batch_number > 0),
  from_position bigint NOT NULL CHECK (from_position > 0),
  previous_hash text NOT NULL,
  frames jsonb NOT NULL,
  hash text NOT NULL,
  canonical_bytes integer NOT NULL CHECK (canonical_bytes > 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (turn_id, batch_number)
);
-- END product/migrations/0007_chat_turns.sql

-- BEGIN product/migrations/0008_flow_runtime_host_bindings.sql
-- Durable authority for one canonical TypeScript host per authorized
-- workspace/catalog binding. These rows do not contain graph or run state;
-- Control's journal remains the only runtime authority.
CREATE TABLE flow_runtime_host_bindings (
    id UUID PRIMARY KEY,
    tenant_id TEXT NOT NULL,
    principal_id TEXT NOT NULL,
    binding_kind TEXT NOT NULL,
    binding_id TEXT NOT NULL,
    repository_id BIGINT NOT NULL,
    user_id BIGINT NOT NULL,
    workspace_id UUID NOT NULL,
    catalog_key TEXT NOT NULL,
    service_name TEXT NOT NULL,
    runtime_artifact_digest TEXT NOT NULL CHECK (runtime_artifact_digest ~ '^[0-9a-f]{64}$'),
    source_revision TEXT NOT NULL CHECK (source_revision ~ '^[0-9a-f]{40}$'),
    owner_generation BIGINT NOT NULL CHECK (owner_generation > 0),
    credential_ciphertext TEXT NOT NULL,
    credential_hash BYTEA NOT NULL CHECK (octet_length(credential_hash) = 32),
    state TEXT NOT NULL CHECK (state IN ('pending', 'starting', 'running', 'failed', 'retired')),
    last_error_code TEXT NOT NULL DEFAULT '',
    created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
    UNIQUE (workspace_id, catalog_key),
    CHECK (tenant_id <> '' AND principal_id <> '' AND binding_kind <> '' AND binding_id <> ''),
    CHECK (catalog_key ~ '^[a-z][a-z0-9._-]{0,63}$'),
    CHECK (service_name ~ '^[A-Za-z0-9_.@:-]{1,128}$'),
    CHECK (credential_ciphertext <> '')
);

CREATE INDEX flow_runtime_host_bindings_repository
    ON flow_runtime_host_bindings (repository_id, user_id, workspace_id);

-- These immutable identifiers deliberately survive parent deletion. A live
-- binding is admitted only while Store holds a share lock on its workspace.
-- Workspace deletion (also reached through repository/user FK cascades) leaves
-- a durable cleanup record, never a lost process/bearer or a blocked deletion.
CREATE FUNCTION retire_deleted_workspace_flow_hosts() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    UPDATE flow_runtime_host_bindings
       SET state = 'retired', updated_at = clock_timestamp()
     WHERE workspace_id = OLD.id AND state <> 'retired';
    RETURN OLD;
END;
$$;
CREATE TRIGGER retire_deleted_workspace_flow_hosts
    BEFORE DELETE ON workspaces FOR EACH ROW
    EXECUTE FUNCTION retire_deleted_workspace_flow_hosts();

CREATE FUNCTION retire_tombstoned_workspace_flow_hosts() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.deleted_at IS NOT NULL THEN
        UPDATE flow_runtime_host_bindings
           SET state = 'retired', updated_at = clock_timestamp()
         WHERE workspace_id = NEW.id AND state <> 'retired';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER retire_tombstoned_workspace_flow_hosts
    AFTER UPDATE OF deleted_at ON workspaces FOR EACH ROW
    EXECUTE FUNCTION retire_tombstoned_workspace_flow_hosts();

CREATE INDEX flow_runtime_host_bindings_retired
    ON flow_runtime_host_bindings (updated_at, id) WHERE state = 'retired';
-- END product/migrations/0008_flow_runtime_host_bindings.sql

-- BEGIN product/migrations/0009_owner_models.sql
-- Model credentials and the selected chat model belong to the account.
-- A repository secret may still override a repository-scoped turn.
CREATE TABLE owner_model_credentials (
    user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    origin TEXT NOT NULL,
    value_encrypted TEXT,
    PRIMARY KEY (user_id, name)
);

CREATE TABLE owner_model_defaults (
    user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    model JSONB NOT NULL
);

CREATE TABLE owner_model_credential_receipts (
    user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    request_id TEXT NOT NULL,
    result JSONB NOT NULL,
    PRIMARY KEY (user_id, request_id)
);
-- END product/migrations/0009_owner_models.sql

-- BEGIN product/migrations/0010_branch_lock_and_workflow_invocations.sql
-- Product branch-lock generation and durable workflow invocation state.
-- Approval belongs to one acquisition of a branch, not every future holder.
ALTER TABLE branch_locks
    ADD COLUMN generation UUID NOT NULL DEFAULT gen_random_uuid();

-- Historical requests cannot be proven to belong to the current acquisition.
-- Keep the audit rows while requiring a fresh request for current membership.
ALTER TABLE branch_lock_join_requests
    ADD COLUMN lock_generation UUID NOT NULL DEFAULT gen_random_uuid();
ALTER TABLE branch_lock_join_requests ALTER COLUMN lock_generation DROP DEFAULT;

DROP INDEX uq_branch_lock_join_requests_pending;
CREATE UNIQUE INDEX uq_branch_lock_join_requests_pending
    ON branch_lock_join_requests (repository_id, branch, lock_generation, requester_id)
    WHERE status = 'pending';

-- Public invocation retains its runtime and source independently of mutable definitions.
CREATE TABLE workflow_invocations (
    workflow_run_id BIGINT PRIMARY KEY REFERENCES workflow_runs(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
    repository_id BIGINT NOT NULL REFERENCES repositories(id) ON DELETE CASCADE,
    workflow_definition_id BIGINT NOT NULL REFERENCES workflow_definitions(id) ON DELETE CASCADE,
    runtime TEXT NOT NULL CHECK (runtime IN ('native-flow-v1', 'legacy-orchestrator-0.28')),
    request_key TEXT NOT NULL,
    request_digest TEXT NOT NULL,
    flow_path TEXT NOT NULL,
    flow_tag TEXT NOT NULL,
    source_commit TEXT NOT NULL,
    source_digest TEXT NOT NULL,
    dispatch_inputs JSONB NOT NULL DEFAULT '{}'::jsonb,
    trigger_event TEXT NOT NULL,
    trigger_ref TEXT NOT NULL,
    sandbox_id TEXT NOT NULL DEFAULT '',
    host_artifact_digest TEXT NOT NULL DEFAULT '',
    plan JSONB,
    run_request JSONB,
    attempted_at TIMESTAMPTZ,
    host_run_id TEXT NOT NULL DEFAULT '',
    final_output JSONB,
    cancel_acknowledged_at TIMESTAMPTZ,
    cleaned_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (repository_id, request_key),
    CHECK (runtime <> 'native-flow-v1' OR (flow_path = 'flows/' || flow_tag || '/flow.ts' AND source_commit <> '' AND source_digest ~ '^[a-f0-9]{64}$')),
    CHECK (run_request IS NULL OR COALESCE(jsonb_typeof(run_request) = 'object' AND run_request->>'_tag' = 'Plan' AND run_request->>'planId' <> '' AND run_request->>'digest' <> '' AND run_request->>'idempotencyKey' = 'workflow-invoke:' || workflow_run_id::text || ':run', FALSE))
);
CREATE INDEX workflow_invocations_pending_cleanup ON workflow_invocations (workflow_run_id) WHERE runtime = 'native-flow-v1' AND cleaned_at IS NULL;

-- Existing sandbox rows may gain tasks after admission; their NixCI selection
-- still takes precedence. No-task rows keep this explicit legacy drain identity.
INSERT INTO workflow_invocations (workflow_run_id, repository_id, workflow_definition_id, runtime, request_key, request_digest, flow_path, flow_tag, source_commit, source_digest, dispatch_inputs, trigger_event, trigger_ref)
SELECT wr.id, wr.repository_id, wr.workflow_definition_id, 'legacy-orchestrator-0.28', 'legacy:' || wr.id::text, '', wd.path, wd.name, wr.trigger_commit_sha, '', COALESCE(wr.dispatch_inputs, '{}'::jsonb), wr.trigger_event, wr.trigger_ref
FROM workflow_runs wr JOIN workflow_definitions wd ON wd.id = wr.workflow_definition_id
WHERE wr.execution_plane = 'sandbox';
-- END product/migrations/0010_branch_lock_and_workflow_invocations.sql

-- BEGIN product/migrations/0011_onboarding_and_workspace_setup.sql
-- Durable product onboarding and workspace setup receipts.
CREATE TABLE public.onboarding_answers (
    user_id bigint NOT NULL,
    answers jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT onboarding_answers_object CHECK ((jsonb_typeof(answers) = 'object'::text))
);

CREATE TABLE public.workspace_setup_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id bigint NOT NULL,
    idempotency_key text NOT NULL,
    request jsonb NOT NULL,
    status text DEFAULT 'accepted'::text NOT NULL,
    workflow_run_id bigint,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT workspace_setup_request_object CHECK ((jsonb_typeof(request) = 'object'::text)),
    CONSTRAINT workspace_setup_status CHECK ((status = ANY (ARRAY['accepted'::text, 'queued'::text, 'running'::text, 'succeeded'::text, 'failed'::text])))
);

ALTER TABLE ONLY public.onboarding_answers
    ADD CONSTRAINT onboarding_answers_pkey PRIMARY KEY (user_id);

ALTER TABLE ONLY public.workspace_setup_jobs
    ADD CONSTRAINT workspace_setup_jobs_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.workspace_setup_jobs
    ADD CONSTRAINT workspace_setup_jobs_user_id_idempotency_key_key UNIQUE (user_id, idempotency_key);

CREATE INDEX workspace_setup_jobs_user_created_idx ON public.workspace_setup_jobs USING btree (user_id, created_at DESC);

ALTER TABLE ONLY public.onboarding_answers
    ADD CONSTRAINT onboarding_answers_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.users(id) ON DELETE CASCADE;

ALTER TABLE ONLY public.workspace_setup_jobs
    ADD CONSTRAINT workspace_setup_jobs_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.users(id) ON DELETE CASCADE;

ALTER TABLE ONLY public.workspace_setup_jobs
    ADD CONSTRAINT workspace_setup_jobs_workflow_run_id_fkey FOREIGN KEY (workflow_run_id) REFERENCES public.workflow_runs(id) ON DELETE SET NULL;
-- END product/migrations/0011_onboarding_and_workspace_setup.sql

-- BEGIN product/migrations/0012_workflow_run_coding_hosts.sql
-- Link the product workflow projection to its canonical coding Flow receipt.
-- Keep the existing Plue object definitions so adoption can recognize them.
CREATE TABLE public.workflow_run_coding_hosts (
    workflow_run_id bigint NOT NULL,
    workspace_id uuid NOT NULL,
    host_run_id text NOT NULL,
    flow_id text NOT NULL,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT workflow_run_coding_hosts_flow_id_present CHECK ((flow_id <> ''::text)),
    CONSTRAINT workflow_run_coding_hosts_host_run_id_present CHECK ((host_run_id <> ''::text))
);

ALTER TABLE ONLY public.workflow_run_coding_hosts
    ADD CONSTRAINT workflow_run_coding_hosts_pkey PRIMARY KEY (workflow_run_id);

CREATE INDEX idx_workflow_run_coding_hosts_workspace ON public.workflow_run_coding_hosts USING btree (workspace_id, workflow_run_id);

ALTER TABLE ONLY public.workflow_run_coding_hosts
    ADD CONSTRAINT workflow_run_coding_hosts_workflow_run_id_fkey FOREIGN KEY (workflow_run_id) REFERENCES public.workflow_runs(id) ON DELETE CASCADE;

ALTER TABLE ONLY public.workflow_run_coding_hosts
    ADD CONSTRAINT workflow_run_coding_hosts_workspace_id_fkey FOREIGN KEY (workspace_id) REFERENCES public.workspaces(id) ON DELETE CASCADE;
-- END product/migrations/0012_workflow_run_coding_hosts.sql

-- BEGIN product/migrations/0013_chat_turn_erasures.sql
CREATE TABLE chat_turn_erasures (
  run_id text NOT NULL,
  leg_id text NOT NULL,
  access_hash text NOT NULL,
  retired_at timestamptz NOT NULL,
  PRIMARY KEY (run_id, leg_id)
);
-- END product/migrations/0013_chat_turn_erasures.sql

-- BEGIN cluster/private_baseline.sql
-- Plue hosted infrastructure baseline. Extracted from the previous full schema.
-- Product tables and durable repository storage operations are authored only by
-- db/product/migrations. Repository placement lives in plue_storage.
-- The old public.repo_storage_* tables remain transitional private state until
-- the Plue cutover migration finishes.
SET check_function_bodies = false;

-- Name: enqueue_issue_artifact_storage_deletion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_issue_artifact_storage_deletion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_repo repositories%ROWTYPE;
BEGIN
    SELECT * INTO v_repo FROM repositories WHERE id = OLD.repository_id;
    IF FOUND THEN
        PERFORM enqueue_storage_deletion(OLD.repository_id,
            CASE WHEN v_repo.user_id IS NOT NULL THEN 'user' ELSE 'org' END,
            COALESCE(v_repo.user_id, v_repo.org_id),
            format('issue-artifact:%s', OLD.id), OLD.gcs_key, OLD.size, NOW());
        PERFORM enqueue_storage_deletion(OLD.repository_id,
            CASE WHEN v_repo.user_id IS NOT NULL THEN 'user' ELSE 'org' END,
            COALESCE(v_repo.user_id, v_repo.org_id),
            format('issue-artifact:%s', OLD.id),
            format('pending/issue-artifacts/%s', LTRIM(OLD.gcs_key, '/')),
            OLD.size, GREATEST(NOW(), OLD.created_at + INTERVAL '7 days 15 minutes'));
    END IF;
    RETURN OLD;
END;
$$;


--

-- Name: enqueue_lfs_object_storage_deletion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_lfs_object_storage_deletion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_repo repositories%ROWTYPE;
BEGIN
    SELECT * INTO v_repo FROM repositories WHERE id = OLD.repository_id;
    IF FOUND THEN
        IF POSITION(
            ',' || OLD.repository_id::text || ',' IN
            COALESCE(current_setting('smithers.deleting_repository_ids', TRUE), '')
        ) = 0 AND TG_OP = 'DELETE' AND EXISTS (
            SELECT 1 FROM lfs_upload_reservations
            WHERE repository_id = OLD.repository_id AND oid = OLD.oid
        ) THEN
            DELETE FROM storage_deletion_queue
            WHERE object_key IN (
                OLD.gcs_path,
                format('lfs-pending/%s/%s', OLD.repository_id, OLD.oid)
            );
            RETURN OLD;
        END IF;
        PERFORM enqueue_storage_deletion(OLD.repository_id,
            CASE WHEN v_repo.user_id IS NOT NULL THEN 'user' ELSE 'org' END,
            COALESCE(v_repo.user_id, v_repo.org_id),
            format('lfs:%s:%s', OLD.repository_id, OLD.oid),
            OLD.gcs_path, OLD.size, NOW());
        PERFORM enqueue_storage_deletion(OLD.repository_id,
            CASE WHEN v_repo.user_id IS NOT NULL THEN 'user' ELSE 'org' END,
            COALESCE(v_repo.user_id, v_repo.org_id),
            format('lfs:%s:%s', OLD.repository_id, OLD.oid),
            format('lfs-pending/%s/%s', OLD.repository_id, OLD.oid), OLD.size,
            NOW() + INTERVAL '7 days 15 minutes');
    END IF;
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END;
$$;


--

-- Name: enqueue_lfs_reservation_storage_deletion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_lfs_reservation_storage_deletion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_repo repositories%ROWTYPE;
BEGIN
    SELECT * INTO v_repo FROM repositories WHERE id = OLD.repository_id;
    IF FOUND THEN
        IF POSITION(
            ',' || OLD.repository_id::text || ',' IN
            COALESCE(current_setting('smithers.deleting_repository_ids', TRUE), '')
        ) = 0 AND TG_OP = 'DELETE' AND EXISTS (
            SELECT 1 FROM lfs_objects
            WHERE repository_id = OLD.repository_id AND oid = OLD.oid
        ) THEN
            DELETE FROM storage_deletion_queue
            WHERE object_key IN (
                format('lfs-pending/%s/%s', OLD.repository_id, OLD.oid),
                format('repos/%s/lfs/%s', OLD.repository_id, OLD.oid)
            );
            RETURN OLD;
        END IF;
        PERFORM enqueue_storage_deletion(OLD.repository_id,
            CASE WHEN v_repo.user_id IS NOT NULL THEN 'user' ELSE 'org' END,
            COALESCE(v_repo.user_id, v_repo.org_id),
            format('lfs:%s:%s', OLD.repository_id, OLD.oid),
            format('lfs-pending/%s/%s', OLD.repository_id, OLD.oid), OLD.size,
            GREATEST(NOW(), OLD.expires_at));
        PERFORM enqueue_storage_deletion(OLD.repository_id,
            CASE WHEN v_repo.user_id IS NOT NULL THEN 'user' ELSE 'org' END,
            COALESCE(v_repo.user_id, v_repo.org_id),
            format('lfs:%s:%s', OLD.repository_id, OLD.oid),
            format('repos/%s/lfs/%s', OLD.repository_id, OLD.oid), OLD.size,
            NOW());
    END IF;
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END;
$$;


--

-- Name: enqueue_release_asset_storage_deletion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_release_asset_storage_deletion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_repository_id BIGINT;
    v_user_id BIGINT;
    v_org_id BIGINT;
BEGIN
    SELECT rel.repository_id, repo.user_id, repo.org_id
    INTO v_repository_id, v_user_id, v_org_id
    FROM releases AS rel
    JOIN repositories AS repo ON repo.id = rel.repository_id
    WHERE rel.id = OLD.release_id;
    IF FOUND THEN
        PERFORM enqueue_storage_deletion(v_repository_id,
            CASE WHEN v_user_id IS NOT NULL THEN 'user' ELSE 'org' END,
            COALESCE(v_user_id, v_org_id), format('release-asset:%s', OLD.id),
            OLD.gcs_key, OLD.size, NOW());
        PERFORM enqueue_storage_deletion(v_repository_id,
            CASE WHEN v_user_id IS NOT NULL THEN 'user' ELSE 'org' END,
            COALESCE(v_user_id, v_org_id), format('release-asset:%s', OLD.id),
            format('pending/release-assets/%s', LTRIM(OLD.gcs_key, '/')),
            OLD.size, GREATEST(NOW(), OLD.created_at + INTERVAL '7 days 15 minutes'));
    END IF;
    RETURN OLD;
END;
$$;


--

-- Name: enqueue_release_storage_deletions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_release_storage_deletions() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_user_id BIGINT;
    v_org_id BIGINT;
    v_row RECORD;
BEGIN
    SELECT user_id, org_id INTO v_user_id, v_org_id
    FROM repositories WHERE id = OLD.repository_id;
    IF NOT FOUND THEN
        RETURN OLD;
    END IF;
    FOR v_row IN
        SELECT id, gcs_key, size, created_at
        FROM release_assets WHERE release_id = OLD.id
    LOOP
        PERFORM enqueue_storage_deletion(OLD.repository_id,
            CASE WHEN v_user_id IS NOT NULL THEN 'user' ELSE 'org' END,
            COALESCE(v_user_id, v_org_id), format('release-asset:%s', v_row.id),
            v_row.gcs_key, v_row.size, NOW());
        PERFORM enqueue_storage_deletion(OLD.repository_id,
            CASE WHEN v_user_id IS NOT NULL THEN 'user' ELSE 'org' END,
            COALESCE(v_user_id, v_org_id), format('release-asset:%s', v_row.id),
            format('pending/release-assets/%s', LTRIM(v_row.gcs_key, '/')),
            v_row.size,
            GREATEST(NOW(), v_row.created_at + INTERVAL '7 days 15 minutes'));
    END LOOP;
    RETURN OLD;
END;
$$;


--

-- Name: enqueue_repository_storage_deletions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_repository_storage_deletions() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_owner_type TEXT := CASE WHEN OLD.user_id IS NOT NULL THEN 'user' ELSE 'org' END;
    v_owner_id BIGINT := COALESCE(OLD.user_id, OLD.org_id);
    v_row RECORD;
BEGIN
    PERFORM set_config(
        'smithers.deleting_repository_ids',
        COALESCE(NULLIF(current_setting('smithers.deleting_repository_ids', TRUE), ''), ',')
            || OLD.id::text || ',',
        TRUE
    );

    FOR v_row IN
        SELECT oid, size, gcs_path FROM lfs_objects WHERE repository_id = OLD.id
    LOOP
        PERFORM enqueue_storage_deletion(OLD.id, v_owner_type, v_owner_id,
            format('lfs:%s:%s', OLD.id, v_row.oid), v_row.gcs_path,
            v_row.size, NOW());
        -- Registered LFS objects can receive repair URLs long after creation.
        PERFORM enqueue_storage_deletion(OLD.id, v_owner_type, v_owner_id,
            format('lfs:%s:%s', OLD.id, v_row.oid),
            format('lfs-pending/%s/%s', OLD.id, v_row.oid), v_row.size,
            NOW() + INTERVAL '7 days 15 minutes');
    END LOOP;

    FOR v_row IN
        SELECT oid, size, expires_at
        FROM lfs_upload_reservations WHERE repository_id = OLD.id
    LOOP
        PERFORM enqueue_storage_deletion(OLD.id, v_owner_type, v_owner_id,
            format('lfs:%s:%s', OLD.id, v_row.oid),
            format('lfs-pending/%s/%s', OLD.id, v_row.oid), v_row.size,
            GREATEST(NOW(), v_row.expires_at));
        PERFORM enqueue_storage_deletion(OLD.id, v_owner_type, v_owner_id,
            format('lfs:%s:%s', OLD.id, v_row.oid),
            format('repos/%s/lfs/%s', OLD.id, v_row.oid), v_row.size, NOW());
    END LOOP;

    FOR v_row IN
        SELECT object_key, object_size_bytes, status, expires_at,
               finalized_at, created_at
        FROM workflow_caches WHERE repository_id = OLD.id
    LOOP
        PERFORM enqueue_storage_deletion(OLD.id, v_owner_type, v_owner_id,
            format('workflow-cache:%s:%s', OLD.id, v_row.object_key),
            v_row.object_key, v_row.object_size_bytes, NOW());
        PERFORM enqueue_storage_deletion(OLD.id, v_owner_type, v_owner_id,
            format('workflow-cache:%s:%s', OLD.id, v_row.object_key),
            format('pending/workflow-caches/%s', LTRIM(v_row.object_key, '/')),
            v_row.object_size_bytes,
            GREATEST(NOW(), CASE
                WHEN v_row.finalized_at IS NULL THEN v_row.expires_at
                ELSE v_row.finalized_at + INTERVAL '7 days 15 minutes'
            END));
    END LOOP;

    FOR v_row IN
        SELECT id, gcs_key, size, created_at
        FROM workflow_artifacts WHERE repository_id = OLD.id
    LOOP
        PERFORM enqueue_storage_deletion(OLD.id, v_owner_type, v_owner_id,
            format('workflow-artifact:%s', v_row.id), v_row.gcs_key,
            v_row.size, NOW());
        PERFORM enqueue_storage_deletion(OLD.id, v_owner_type, v_owner_id,
            format('workflow-artifact:%s', v_row.id),
            format('pending/workflow-artifacts/%s', LTRIM(v_row.gcs_key, '/')),
            v_row.size,
            GREATEST(NOW(), v_row.created_at + INTERVAL '7 days 15 minutes'));
    END LOOP;

    FOR v_row IN
        SELECT id, gcs_key, size, created_at
        FROM issue_artifacts WHERE repository_id = OLD.id
    LOOP
        PERFORM enqueue_storage_deletion(OLD.id, v_owner_type, v_owner_id,
            format('issue-artifact:%s', v_row.id), v_row.gcs_key,
            v_row.size, NOW());
        PERFORM enqueue_storage_deletion(OLD.id, v_owner_type, v_owner_id,
            format('issue-artifact:%s', v_row.id),
            format('pending/issue-artifacts/%s', LTRIM(v_row.gcs_key, '/')),
            v_row.size,
            GREATEST(NOW(), v_row.created_at + INTERVAL '7 days 15 minutes'));
    END LOOP;

    FOR v_row IN
        SELECT ra.id, ra.gcs_key, ra.size, ra.created_at
        FROM release_assets AS ra
        JOIN releases AS rel ON rel.id = ra.release_id
        WHERE rel.repository_id = OLD.id
    LOOP
        PERFORM enqueue_storage_deletion(OLD.id, v_owner_type, v_owner_id,
            format('release-asset:%s', v_row.id), v_row.gcs_key,
            v_row.size, NOW());
        PERFORM enqueue_storage_deletion(OLD.id, v_owner_type, v_owner_id,
            format('release-asset:%s', v_row.id),
            format('pending/release-assets/%s', LTRIM(v_row.gcs_key, '/')),
            v_row.size,
            GREATEST(NOW(), v_row.created_at + INTERVAL '7 days 15 minutes'));
    END LOOP;
    RETURN OLD;
END;
$$;


--

-- Name: enqueue_storage_deletion(bigint, text, bigint, text, text, bigint, timestamptz); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_storage_deletion(p_repository_id bigint, p_owner_type text, p_owner_id bigint, p_allocation_key text, p_object_key text, p_size_bytes bigint, p_delete_after timestamptz) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_requested_delete_after TIMESTAMPTZ;
    v_horizon TIMESTAMPTZ;
    v_is_staging BOOLEAN;
BEGIN
    IF p_repository_id IS NULL
        OR p_owner_type NOT IN ('user', 'org')
        OR p_owner_id IS NULL
        OR BTRIM(COALESCE(p_allocation_key, '')) = ''
        OR BTRIM(COALESCE(p_object_key, '')) = ''
    THEN
        RETURN;
    END IF;

    v_requested_delete_after := GREATEST(COALESCE(p_delete_after, NOW()), NOW());
    v_is_staging := is_storage_staging_deletion_key(
        p_repository_id, p_allocation_key, p_object_key
    );
    v_horizon := COALESCE(
        (
            SELECT horizon.valid_until
            FROM storage_legacy_capability_horizons AS horizon
            WHERE horizon.capability_kind = 'legacy-final-key-upload'
        ),
        'infinity'::timestamptz
    );

    INSERT INTO storage_deletion_queue (
        repository_id, owner_type, owner_id, allocation_key, object_key,
        size_bytes, delete_after, requested_delete_after
    ) VALUES (
        p_repository_id, p_owner_type, p_owner_id, p_allocation_key,
        p_object_key, GREATEST(COALESCE(p_size_bytes, 0), 0),
        CASE
            WHEN v_is_staging THEN v_requested_delete_after
            WHEN isfinite(v_horizon) THEN GREATEST(v_requested_delete_after, v_horizon)
            ELSE TIMESTAMPTZ '9999-12-31 23:59:59+00'
        END,
        CASE WHEN v_is_staging THEN NULL ELSE v_requested_delete_after END
    )
    ON CONFLICT (object_key) DO UPDATE
    SET repository_id = EXCLUDED.repository_id,
        owner_type = EXCLUDED.owner_type,
        owner_id = EXCLUDED.owner_id,
        allocation_key = EXCLUDED.allocation_key,
        size_bytes = GREATEST(storage_deletion_queue.size_bytes, EXCLUDED.size_bytes),
        delete_after = GREATEST(storage_deletion_queue.delete_after, EXCLUDED.delete_after),
        requested_delete_after = GREATEST(
            storage_deletion_queue.requested_delete_after,
            EXCLUDED.requested_delete_after
        ),
        claim_token = NULL,
        claimed_at = NULL,
        last_error = NULL,
        updated_at = NOW();

    UPDATE storage_deletion_queue AS queue
    SET delete_after = queue.requested_delete_after,
        requested_delete_after = NULL,
        updated_at = NOW()
    WHERE queue.repository_id = p_repository_id
      AND queue.allocation_key = p_allocation_key
      AND queue.requested_delete_after IS NOT NULL
      AND is_storage_staging_deletion_key(
          queue.repository_id, queue.allocation_key, queue.object_key
      );
END;
$$;


--

-- Name: enqueue_workflow_artifact_storage_deletion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_workflow_artifact_storage_deletion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_repo repositories%ROWTYPE;
BEGIN
    SELECT * INTO v_repo FROM repositories WHERE id = OLD.repository_id;
    IF FOUND THEN
        PERFORM enqueue_storage_deletion(OLD.repository_id,
            CASE WHEN v_repo.user_id IS NOT NULL THEN 'user' ELSE 'org' END,
            COALESCE(v_repo.user_id, v_repo.org_id),
            format('workflow-artifact:%s', OLD.id), OLD.gcs_key, OLD.size, NOW());
        PERFORM enqueue_storage_deletion(OLD.repository_id,
            CASE WHEN v_repo.user_id IS NOT NULL THEN 'user' ELSE 'org' END,
            COALESCE(v_repo.user_id, v_repo.org_id),
            format('workflow-artifact:%s', OLD.id),
            format('pending/workflow-artifacts/%s', LTRIM(OLD.gcs_key, '/')),
            OLD.size, GREATEST(NOW(), OLD.created_at + INTERVAL '7 days 15 minutes'));
    END IF;
    RETURN OLD;
END;
$$;


--

-- Name: enqueue_workflow_cache_storage_deletion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_workflow_cache_storage_deletion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_repo repositories%ROWTYPE;
BEGIN
    SELECT * INTO v_repo FROM repositories WHERE id = OLD.repository_id;
    IF FOUND THEN
        PERFORM enqueue_storage_deletion(OLD.repository_id,
            CASE WHEN v_repo.user_id IS NOT NULL THEN 'user' ELSE 'org' END,
            COALESCE(v_repo.user_id, v_repo.org_id),
            format('workflow-cache:%s:%s', OLD.repository_id, OLD.object_key),
            OLD.object_key, OLD.object_size_bytes, NOW());
        PERFORM enqueue_storage_deletion(OLD.repository_id,
            CASE WHEN v_repo.user_id IS NOT NULL THEN 'user' ELSE 'org' END,
            COALESCE(v_repo.user_id, v_repo.org_id),
            format('workflow-cache:%s:%s', OLD.repository_id, OLD.object_key),
            format('pending/workflow-caches/%s', LTRIM(OLD.object_key, '/')),
            OLD.object_size_bytes,
            GREATEST(NOW(), CASE
                WHEN OLD.finalized_at IS NULL THEN OLD.expires_at
                ELSE OLD.finalized_at + INTERVAL '7 days 15 minutes'
            END));
    END IF;
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END;
$$;


--

-- Name: guard_storage_legacy_capability_horizon(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_storage_legacy_capability_horizon() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'storage legacy capability horizon cannot be deleted'
            USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.capability_kind IS DISTINCT FROM OLD.capability_kind THEN
        RAISE EXCEPTION 'storage legacy capability kind is immutable'
            USING ERRCODE = 'check_violation';
    END IF;
    IF NOT isfinite(NEW.valid_until) OR NEW.valid_until <= clock_timestamp() THEN
        RAISE EXCEPTION 'legacy capability horizon must be a finite future timestamp'
            USING ERRCODE = 'check_violation';
    END IF;
    IF isfinite(OLD.valid_until) AND OLD.valid_until <= clock_timestamp() THEN
        RAISE EXCEPTION 'legacy capability horizon cannot change after purge has opened'
            USING ERRCODE = 'check_violation';
    END IF;
    IF isfinite(OLD.valid_until) AND NEW.valid_until < OLD.valid_until THEN
        RAISE EXCEPTION 'legacy capability horizon can only be extended'
            USING ERRCODE = 'check_violation';
    END IF;
    IF BTRIM(COALESCE(NEW.attested_by, '')) = ''
       OR BTRIM(COALESCE(NEW.attestation, '')) = '' THEN
        RAISE EXCEPTION 'legacy capability horizon requires operator and evidence'
            USING ERRCODE = 'check_violation';
    END IF;

    NEW.attested_at := NOW();
    RETURN NEW;
END;
$$;


--

-- Name: guard_workflow_sandbox_terminal_claim(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_workflow_sandbox_terminal_claim() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    active_claim workflow_sandbox_claims%ROWTYPE;
BEGIN
    IF OLD.execution_plane IS DISTINCT FROM 'sandbox'
       OR NEW.status NOT IN ('success', 'failure') THEN
        RETURN NEW;
    END IF;

    IF OLD.status = 'queued' THEN
        RETURN NULL;
    END IF;

    SELECT *
    INTO active_claim
    FROM workflow_sandbox_claims
    WHERE workflow_run_id = OLD.id
      AND claim_token IS NOT NULL;

    IF FOUND
       AND (
           current_setting('smithers.workflow_sandbox_claim_token', true)
               IS DISTINCT FROM active_claim.claim_token::text
           OR current_setting('smithers.workflow_sandbox_claim_generation', true)
               IS DISTINCT FROM active_claim.generation::text
       ) THEN
        RETURN NULL;
    END IF;

    RETURN NEW;
END;
$$;


--

-- Name: guard_workspace_gateway_sharing(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_workspace_gateway_sharing() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE bound_workspace uuid;
BEGIN
    IF TG_TABLE_NAME = 'repo_gateways' THEN
        IF NEW.workspace_id IS NULL OR NEW.deleted_at IS NOT NULL
           OR NEW.status IN ('stopped', 'failed') THEN RETURN NEW; END IF;
        bound_workspace := NEW.workspace_id;
        PERFORM 1 FROM workspaces WHERE id = bound_workspace FOR UPDATE;
        IF EXISTS (SELECT 1 FROM workspace_shares WHERE workspace_id = bound_workspace AND level = 'write') THEN
            RAISE EXCEPTION 'workspace coding gateway conflicts with write sharing'
                USING ERRCODE = '23514', CONSTRAINT = 'workspace_gateway_private_execution';
        END IF;
    ELSE
        IF NEW.level <> 'write' THEN RETURN NEW; END IF;
        bound_workspace := NEW.workspace_id;
        PERFORM 1 FROM workspaces WHERE id = bound_workspace FOR UPDATE;
        IF EXISTS (SELECT 1 FROM repo_gateways WHERE workspace_id = bound_workspace
                   AND (auth_token_hash <> '' OR (deleted_at IS NULL AND status NOT IN ('stopped', 'failed')))) THEN
            RAISE EXCEPTION 'workspace write sharing conflicts with coding gateway'
                USING ERRCODE = '23514', CONSTRAINT = 'workspace_gateway_private_execution';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--

-- Name: invalidate_workflow_sandbox_claim(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invalidate_workflow_sandbox_claim() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.execution_plane = 'sandbox'
       AND NEW.status IN ('success', 'failure', 'cancelled')
       AND NEW.status IS DISTINCT FROM OLD.status THEN
        UPDATE workflow_sandbox_claims
        SET generation = generation + 1,
            claim_token = NULL,
            claimed_at = NULL,
            lease_expires_at = NULL
        WHERE workflow_run_id = NEW.id
          AND claim_token IS NOT NULL;
    END IF;

    RETURN NULL;
END;
$$;


--

-- Name: is_storage_staging_deletion_key(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_storage_staging_deletion_key(p_repository_id bigint, p_allocation_key text, p_object_key text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT CASE
        WHEN p_allocation_key LIKE 'lfs:%' THEN
            p_object_key = format(
                'lfs-pending/%s/%s',
                split_part(p_allocation_key, ':', 2),
                split_part(p_allocation_key, ':', 3)
            )
            AND split_part(p_allocation_key, ':', 4) = ''
            AND EXISTS (
                SELECT 1
                FROM storage_deletion_queue AS sibling
                WHERE sibling.repository_id = p_repository_id
                  AND sibling.allocation_key = p_allocation_key
                  AND sibling.object_key <> p_object_key
            )
        WHEN p_allocation_key LIKE 'workflow-cache:%' THEN
            EXISTS (
                SELECT 1
                FROM storage_deletion_queue AS sibling
                WHERE sibling.repository_id = p_repository_id
                  AND sibling.allocation_key = p_allocation_key
                  AND sibling.object_key <> p_object_key
                  AND p_object_key = format(
                      'pending/workflow-caches/%s', LTRIM(sibling.object_key, '/')
                  )
            )
        WHEN p_allocation_key LIKE 'workflow-artifact:%' THEN
            EXISTS (
                SELECT 1
                FROM storage_deletion_queue AS sibling
                WHERE sibling.repository_id = p_repository_id
                  AND sibling.allocation_key = p_allocation_key
                  AND sibling.object_key <> p_object_key
                  AND p_object_key = format(
                      'pending/workflow-artifacts/%s', LTRIM(sibling.object_key, '/')
                  )
            )
        WHEN p_allocation_key LIKE 'issue-artifact:%' THEN
            EXISTS (
                SELECT 1
                FROM storage_deletion_queue AS sibling
                WHERE sibling.repository_id = p_repository_id
                  AND sibling.allocation_key = p_allocation_key
                  AND sibling.object_key <> p_object_key
                  AND p_object_key = format(
                      'pending/issue-artifacts/%s', LTRIM(sibling.object_key, '/')
                  )
            )
        WHEN p_allocation_key LIKE 'release-asset:%' THEN
            EXISTS (
                SELECT 1
                FROM storage_deletion_queue AS sibling
                WHERE sibling.repository_id = p_repository_id
                  AND sibling.allocation_key = p_allocation_key
                  AND sibling.object_key <> p_object_key
                  AND p_object_key = format(
                      'pending/release-assets/%s', LTRIM(sibling.object_key, '/')
                  )
            )
        ELSE FALSE
    END;
$$;


--

-- Name: sandbox_environment_images; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sandbox_environment_images (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    repository_id bigint,
    kind text NOT NULL,
    source text DEFAULT '.smithers/environment.nix'::text NOT NULL,
    source_revision text DEFAULT ''::text NOT NULL,
    closure_hash text NOT NULL,
    image text NOT NULL,
    status text DEFAULT 'ready'::text NOT NULL,
    created_by bigint,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT sandbox_environment_images_closure_hash_check CHECK ((closure_hash <> ''::text)),
    CONSTRAINT sandbox_environment_images_image_check CHECK ((image <> ''::text)),
    CONSTRAINT sandbox_environment_images_kind_check CHECK ((kind = ANY (ARRAY['vm'::text, 'desktop'::text]))),
    CONSTRAINT sandbox_environment_images_status_check CHECK ((status = ANY (ARRAY['ready'::text, 'retired'::text])))
);


--

-- Name: register_sandbox_environment_image(bigint, text, text, text, text, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_sandbox_environment_image(p_repository_id bigint, p_kind text, p_source text, p_source_revision text, p_closure_hash text, p_image text, p_created_by bigint) RETURNS public.sandbox_environment_images
    LANGUAGE plpgsql
    AS $$
DECLARE
    registered sandbox_environment_images%ROWTYPE;
BEGIN
    IF p_repository_id IS NULL THEN
        PERFORM pg_advisory_xact_lock(hashtextextended('sandbox-base:' || p_kind, 0));
        UPDATE sandbox_environment_images
        SET status = 'retired', updated_at = NOW()
        WHERE repository_id IS NULL
          AND kind = p_kind
          AND closure_hash <> p_closure_hash
          AND status = 'ready';
    END IF;

    INSERT INTO sandbox_environment_images (
        repository_id, kind, source, source_revision, closure_hash, image, created_by
    ) VALUES (
        p_repository_id, p_kind,
        COALESCE(NULLIF(p_source, ''), '.smithers/environment.nix'),
        p_source_revision, p_closure_hash, p_image, p_created_by
    )
    ON CONFLICT ((COALESCE(repository_id, 0)), kind, closure_hash) DO UPDATE SET
        image = EXCLUDED.image,
        source = EXCLUDED.source,
        source_revision = EXCLUDED.source_revision,
        status = 'ready',
        updated_at = NOW()
    RETURNING * INTO registered;

    RETURN registered;
END;
$$;


--

-- Name: resolve_recreated_lfs_storage_keys(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_recreated_lfs_storage_keys() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_TABLE_NAME = 'lfs_objects' THEN
        DELETE FROM storage_deletion_queue
        WHERE object_key IN (
            NEW.gcs_path,
            format('lfs-pending/%s/%s', NEW.repository_id, NEW.oid)
        );
    ELSE
        DELETE FROM storage_deletion_queue
        WHERE object_key IN (
            format('lfs-pending/%s/%s', NEW.repository_id, NEW.oid),
            format('repos/%s/lfs/%s', NEW.repository_id, NEW.oid)
        );
    END IF;
    RETURN NEW;
END;
$$;


--

-- Name: retarget_repository_storage_deletions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.retarget_repository_storage_deletions() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE storage_deletion_queue
    SET owner_type = CASE WHEN NEW.user_id IS NOT NULL THEN 'user' ELSE 'org' END,
        owner_id = COALESCE(NEW.user_id, NEW.org_id),
        updated_at = NOW()
    WHERE repository_id = NEW.id;
    RETURN NEW;
END;
$$;


--

-- Name: validate_repository_provisioning_operation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_repository_provisioning_operation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_owner_name TEXT;
    v_owner_type TEXT;
    v_owner_id BIGINT;
    v_source RECORD;
    v_authorized BOOLEAN;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        IF NEW.repository_id IS DISTINCT FROM OLD.repository_id
           OR NEW.operation_type IS DISTINCT FROM OLD.operation_type
           OR NEW.token IS DISTINCT FROM OLD.token
           OR NEW.actor_id IS DISTINCT FROM OLD.actor_id
           OR NEW.storage_set_id IS DISTINCT FROM OLD.storage_set_id
           OR NEW.owner_name IS DISTINCT FROM OLD.owner_name
           OR NEW.user_id IS DISTINCT FROM OLD.user_id
           OR NEW.org_id IS DISTINCT FROM OLD.org_id
           OR NEW.name IS DISTINCT FROM OLD.name
           OR NEW.lower_name IS DISTINCT FROM OLD.lower_name
           OR NEW.description IS DISTINCT FROM OLD.description
           OR NEW.is_public IS DISTINCT FROM OLD.is_public
           OR NEW.default_bookmark IS DISTINCT FROM OLD.default_bookmark
           OR NEW.auto_init IS DISTINCT FROM OLD.auto_init
           OR NEW.is_fork IS DISTINCT FROM OLD.is_fork
           OR NEW.fork_id IS DISTINCT FROM OLD.fork_id
           OR NEW.source_repository_id IS DISTINCT FROM OLD.source_repository_id
           OR NEW.source_owner IS DISTINCT FROM OLD.source_owner
           OR NEW.source_repo IS DISTINCT FROM OLD.source_repo
           OR NEW.source_storage_set_id IS DISTINCT FROM OLD.source_storage_set_id THEN
            RAISE EXCEPTION USING ERRCODE = '0A000',
                MESSAGE = 'repository provisioning identity is immutable';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.user_id IS NOT NULL THEN
        v_owner_type := 'user';
        v_owner_id := NEW.user_id;
        SELECT username INTO v_owner_name FROM users WHERE id = NEW.user_id FOR KEY SHARE;
    ELSE
        v_owner_type := 'org';
        v_owner_id := NEW.org_id;
        SELECT name INTO v_owner_name FROM organizations WHERE id = NEW.org_id FOR KEY SHARE;
    END IF;
    IF v_owner_name IS NULL OR v_owner_name IS DISTINCT FROM NEW.owner_name THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'repository provisioning owner identity does not match';
    END IF;
    PERFORM 1 FROM users WHERE id = NEW.actor_id FOR KEY SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'repository provisioning actor does not exist';
    END IF;
    IF NEW.user_id IS NOT NULL THEN
        IF NEW.actor_id IS DISTINCT FROM NEW.user_id THEN
            RAISE EXCEPTION USING ERRCODE = '42501',
                MESSAGE = 'repository provisioning actor cannot create for this user';
        END IF;
    ELSE
        PERFORM 1 FROM org_members
        WHERE organization_id = NEW.org_id AND user_id = NEW.actor_id AND role = 'owner'
        FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE = '42501',
                MESSAGE = 'repository provisioning actor is not an organization owner';
        END IF;
    END IF;
    IF NEW.operation_type = 'fork' THEN
        SELECT r.user_id, r.org_id, r.name, p.storage_set_id, r.is_public,
               COALESCE(u.username, o.name) AS owner_name
        INTO v_source
        FROM repositories r
        LEFT JOIN plue_storage.repository_placements p ON p.repository_id = r.id AND p.state = 'published'
        LEFT JOIN users u ON u.id = r.user_id
        LEFT JOIN organizations o ON o.id = r.org_id
        WHERE r.id = NEW.source_repository_id
        FOR UPDATE OF r;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE = '23514',
                MESSAGE = 'repository provisioning source identity does not match';
        END IF;
        IF v_source.owner_name IS DISTINCT FROM NEW.source_owner
           OR v_source.name IS DISTINCT FROM NEW.source_repo
           OR v_source.storage_set_id IS DISTINCT FROM NEW.source_storage_set_id THEN
            RAISE EXCEPTION USING ERRCODE = '23514',
                MESSAGE = 'repository provisioning source identity does not match';
        END IF;
        IF NOT v_source.is_public THEN
            -- Comparisons against an organization-owned source yield NULL for
            -- user_id. Normalize that three-valued result before using it as
            -- an authorization accumulator; otherwise every subsequent
            -- "IF NOT v_authorized" guard is skipped.
            v_authorized := COALESCE(v_source.user_id = NEW.actor_id, FALSE);
            IF NOT v_authorized AND v_source.org_id IS NOT NULL THEN
                SELECT TRUE INTO v_authorized
                FROM org_members om
                WHERE om.organization_id = v_source.org_id
                  AND om.user_id = NEW.actor_id
                  AND om.role = 'owner'
                FOR UPDATE OF om;
                v_authorized := COALESCE(v_authorized, FALSE);
            END IF;
            IF NOT v_authorized AND v_source.org_id IS NOT NULL THEN
                SELECT TRUE INTO v_authorized
                FROM team_repos tr
                JOIN teams t ON t.id = tr.team_id
                JOIN team_members tm ON tm.team_id = t.id
                JOIN org_members om
                  ON om.organization_id = t.organization_id
                 AND om.user_id = tm.user_id
                WHERE tr.repository_id = NEW.source_repository_id
                  AND tm.user_id = NEW.actor_id
                  AND t.organization_id = v_source.org_id
                  AND t.permission IN ('read', 'write', 'admin')
                LIMIT 1
                FOR UPDATE OF tr, t, tm, om;
                v_authorized := COALESCE(v_authorized, FALSE);
            END IF;
            IF NOT v_authorized THEN
                SELECT TRUE INTO v_authorized
                FROM collaborators c
                WHERE c.repository_id = NEW.source_repository_id
                  AND c.user_id = NEW.actor_id
                  AND c.permission IN ('read', 'write', 'admin')
                FOR UPDATE OF c;
                v_authorized := COALESCE(v_authorized, FALSE);
            END IF;
            IF NOT v_authorized THEN
                RAISE EXCEPTION USING ERRCODE = '42501',
                    MESSAGE = 'repository provisioning actor cannot read fork source';
            END IF;
        END IF;
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended(
        FORMAT('repository-provision:%s:%s:%s', v_owner_type, v_owner_id, NEW.lower_name), 0
    ));
    IF EXISTS (
        SELECT 1 FROM repositories
        WHERE lower_name = NEW.lower_name
          AND ((NEW.user_id IS NOT NULL AND user_id = NEW.user_id)
               OR (NEW.org_id IS NOT NULL AND org_id = NEW.org_id))
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23505',
            MESSAGE = 'repository provisioning namespace is already occupied';
    END IF;
    RETURN NEW;
END;
$$;


