-- attests that all legacy final-key uploaders have drained.
INSERT INTO public.storage_legacy_capability_horizons (capability_kind, valid_until)
VALUES ('legacy-final-key-upload', 'infinity'::timestamptz)
ON CONFLICT (capability_kind) DO NOTHING;
-- END cluster/private_baseline.sql
CREATE SCHEMA IF NOT EXISTS plue_storage;

-- BEGIN cluster/migrations/0001_repository_storage_routing.sql
-- Plue-private repository storage membership and routing. Product repository
-- rows keep only their stable storage_set_id; node addresses, capacity, drain
-- state, and fencing generations are deployment infrastructure.
CREATE TABLE IF NOT EXISTS plue_storage.storage_sets (
    id                 TEXT PRIMARY KEY CHECK (id ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$'),
    state              TEXT NOT NULL DEFAULT 'active'
                       CHECK (state IN ('active', 'draining', 'disabled')),
    routing_generation BIGINT NOT NULL DEFAULT 1 CHECK (routing_generation >= 1),
    active_node_id     TEXT,
    capacity_bytes     BIGINT NOT NULL CHECK (capacity_bytes > 0),
    reserved_bytes     BIGINT NOT NULL DEFAULT 0
                       CHECK (reserved_bytes >= 0 AND reserved_bytes <= capacity_bytes),
    created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (id, active_node_id)
);

CREATE TABLE IF NOT EXISTS plue_storage.storage_nodes (
    id             TEXT NOT NULL CHECK (id ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$'),
    storage_set_id TEXT NOT NULL REFERENCES plue_storage.storage_sets(id) ON DELETE CASCADE,
    base_url       TEXT NOT NULL,
    zone           TEXT NOT NULL DEFAULT '',
    activation_generation BIGINT NOT NULL CHECK (activation_generation >= 1),
    state          TEXT NOT NULL DEFAULT 'active'
                   CHECK (state IN ('active', 'draining', 'offline')),
    last_seen_at   TIMESTAMPTZ,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (storage_set_id, id),
    UNIQUE (base_url)
);

ALTER TABLE plue_storage.storage_sets
    ADD CONSTRAINT storage_sets_active_node_fk
    FOREIGN KEY (id, active_node_id)
    REFERENCES plue_storage.storage_nodes(storage_set_id, id)
    DEFERRABLE INITIALLY DEFERRED;

CREATE INDEX IF NOT EXISTS storage_nodes_state_idx
    ON plue_storage.storage_nodes(storage_set_id, state);

CREATE OR REPLACE FUNCTION plue_storage.fence_storage_set_route_update()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.routing_generation < OLD.routing_generation THEN
        RAISE EXCEPTION 'storage-set routing generation cannot decrease';
    END IF;
    IF NEW.active_node_id IS DISTINCT FROM OLD.active_node_id
       AND NEW.routing_generation <= OLD.routing_generation THEN
        RAISE EXCEPTION 'changing the active storage node requires a higher routing generation';
    END IF;
    IF OLD.state = 'disabled' AND NEW.state IN ('active', 'draining')
       AND NEW.routing_generation <= OLD.routing_generation THEN
        RAISE EXCEPTION 're-enabling a storage set requires a higher routing generation';
    END IF;
    NEW.updated_at = now();
    RETURN NEW;
END;
$$;

CREATE TRIGGER storage_sets_fence_route_update
    BEFORE UPDATE ON plue_storage.storage_sets
    FOR EACH ROW EXECUTE FUNCTION plue_storage.fence_storage_set_route_update();
-- END cluster/migrations/0001_repository_storage_routing.sql

-- BEGIN cluster/migrations/0002_repository_placements.sql
-- Product repositories intentionally contain no deployment placement. A row
-- is reserved here before storage is touched and becomes routable only after
-- the matching public repository row has been published.
CREATE TABLE plue_storage.repository_placements (
    repository_id       BIGINT PRIMARY KEY CHECK (repository_id > 0),
    reservation_token   TEXT NOT NULL UNIQUE
                        CHECK (length(reservation_token) BETWEEN 16 AND 256),
    storage_set_id      TEXT NOT NULL
                        REFERENCES plue_storage.storage_sets(id) ON DELETE RESTRICT,
    state               TEXT NOT NULL DEFAULT 'reserved'
                        CHECK (state IN ('reserved', 'published', 'released')),
    capacity_bytes      BIGINT NOT NULL CHECK (capacity_bytes > 0),
    placement_generation BIGINT NOT NULL DEFAULT 1
                        CHECK (placement_generation >= 1),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    published_at        TIMESTAMPTZ,
    released_at         TIMESTAMPTZ,
    CHECK ((state = 'reserved' AND published_at IS NULL AND released_at IS NULL)
        OR (state = 'published' AND published_at IS NOT NULL AND released_at IS NULL)
        OR (state = 'released' AND released_at IS NOT NULL))
);

CREATE INDEX repository_placements_storage_set_state_idx
    ON plue_storage.repository_placements(storage_set_id, state, repository_id);

CREATE OR REPLACE FUNCTION plue_storage.validate_repository_placement_lifecycle()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'repository placement records are durable and cannot be deleted'
            USING ERRCODE = '55000';
    END IF;

    IF TG_OP = 'INSERT' THEN
        IF NEW.state <> 'reserved' OR NEW.placement_generation <> 1 THEN
            RAISE EXCEPTION 'repository placement must begin reserved at generation 1'
                USING ERRCODE = '55000';
        END IF;
        NEW.created_at = now();
        NEW.updated_at = NEW.created_at;
        NEW.published_at = NULL;
        NEW.released_at = NULL;
        RETURN NEW;
    END IF;

    IF NEW.repository_id <> OLD.repository_id
       OR NEW.reservation_token <> OLD.reservation_token
       OR NEW.capacity_bytes <> OLD.capacity_bytes THEN
        RAISE EXCEPTION 'repository placement identity and capacity are immutable'
            USING ERRCODE = '55000';
    END IF;
    IF OLD.state = 'released' AND NEW IS DISTINCT FROM OLD THEN
        RAISE EXCEPTION 'released repository placement cannot be changed'
            USING ERRCODE = '55000';
    END IF;
    IF OLD.state = 'reserved' AND NEW.state NOT IN ('reserved', 'published', 'released') THEN
        RAISE EXCEPTION 'invalid repository placement transition'
            USING ERRCODE = '55000';
    END IF;
    IF OLD.state = 'published' AND NEW.state NOT IN ('published', 'released') THEN
        RAISE EXCEPTION 'published repository placement cannot return to reserved'
            USING ERRCODE = '55000';
    END IF;
    IF NEW.storage_set_id IS DISTINCT FROM OLD.storage_set_id THEN
        IF OLD.state <> 'published' OR NEW.state <> 'published'
           OR NEW.placement_generation <> OLD.placement_generation + 1 THEN
            RAISE EXCEPTION 'repository relocation requires one higher published generation'
                USING ERRCODE = '55000';
        END IF;
    ELSIF NEW.placement_generation <> OLD.placement_generation THEN
        RAISE EXCEPTION 'placement generation changes only during relocation'
            USING ERRCODE = '55000';
    END IF;

    IF OLD.state = 'reserved' AND NEW.state = 'published' THEN
        NEW.published_at = COALESCE(NEW.published_at, now());
    ELSE
        NEW.published_at = OLD.published_at;
    END IF;
    IF NEW.state = 'released' AND OLD.state <> 'released' THEN
        NEW.released_at = COALESCE(NEW.released_at, now());
    ELSE
        NEW.released_at = OLD.released_at;
    END IF;
    NEW.created_at = OLD.created_at;
    NEW.updated_at = now();
    RETURN NEW;
END;
$$;

CREATE TRIGGER repository_placements_validate_lifecycle
    BEFORE INSERT OR UPDATE OR DELETE ON plue_storage.repository_placements
    FOR EACH ROW EXECUTE FUNCTION plue_storage.validate_repository_placement_lifecycle();

-- Keep capacity accounting authoritative in PostgreSQL. The trigger locks the
-- selected set and rechecks admission so direct or concurrent callers cannot
-- overbook a set after observing stale free capacity.
CREATE OR REPLACE FUNCTION plue_storage.account_repository_placement_capacity()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
    admitted BOOLEAN;
BEGIN
    IF TG_OP = 'UPDATE' AND OLD.state <> 'released'
       AND (NEW.state = 'released' OR NEW.storage_set_id IS DISTINCT FROM OLD.storage_set_id) THEN
        UPDATE plue_storage.storage_sets
        SET reserved_bytes = reserved_bytes - OLD.capacity_bytes,
            updated_at = now()
        WHERE id = OLD.storage_set_id AND reserved_bytes >= OLD.capacity_bytes;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'repository placement capacity accounting underflow'
                USING ERRCODE = '55000';
        END IF;
    END IF;

    IF (TG_OP = 'INSERT' AND NEW.state <> 'released')
       OR (TG_OP = 'UPDATE' AND NEW.state <> 'released'
           AND NEW.storage_set_id IS DISTINCT FROM OLD.storage_set_id) THEN
        UPDATE plue_storage.storage_sets AS s
        SET reserved_bytes = s.reserved_bytes + NEW.capacity_bytes,
            updated_at = now()
        WHERE s.id = NEW.storage_set_id
          AND s.state = 'active'
          AND s.capacity_bytes - s.reserved_bytes >= NEW.capacity_bytes
          AND EXISTS (
              SELECT 1
              FROM plue_storage.storage_nodes AS n
              WHERE n.storage_set_id = s.id
                AND n.id = s.active_node_id
                AND n.state = 'active'
                AND n.activation_generation = s.routing_generation
          )
        RETURNING TRUE INTO admitted;
        IF NOT COALESCE(admitted, FALSE) THEN
            RAISE EXCEPTION 'storage set unavailable or capacity exhausted'
                USING ERRCODE = '53100';
        END IF;
    END IF;
    RETURN NULL;
END;
$$;

CREATE TRIGGER repository_placements_account_capacity
    AFTER INSERT OR UPDATE ON plue_storage.repository_placements
    FOR EACH ROW EXECUTE FUNCTION plue_storage.account_repository_placement_capacity();
-- END cluster/migrations/0002_repository_placements.sql

-- BEGIN cluster/migrations/0003_harden_placement_locking.sql
-- Hold the active node row as well as the storage-set row while admitting
-- capacity. This closes the interval in which a node could be marked offline
-- after the availability predicate but before the reservation committed.
CREATE OR REPLACE FUNCTION plue_storage.account_repository_placement_capacity()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
    admitted BOOLEAN;
BEGIN
    IF TG_OP = 'UPDATE' AND OLD.state <> 'released'
       AND (NEW.state = 'released' OR NEW.storage_set_id IS DISTINCT FROM OLD.storage_set_id) THEN
        UPDATE plue_storage.storage_sets
        SET reserved_bytes = reserved_bytes - OLD.capacity_bytes,
            updated_at = now()
        WHERE id = OLD.storage_set_id AND reserved_bytes >= OLD.capacity_bytes;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'repository placement capacity accounting underflow'
                USING ERRCODE = '55000';
        END IF;
    END IF;

    IF (TG_OP = 'INSERT' AND NEW.state <> 'released')
       OR (TG_OP = 'UPDATE' AND NEW.state <> 'released'
           AND NEW.storage_set_id IS DISTINCT FROM OLD.storage_set_id) THEN
        UPDATE plue_storage.storage_sets AS s
        SET reserved_bytes = s.reserved_bytes + NEW.capacity_bytes,
            updated_at = now()
        WHERE s.id = NEW.storage_set_id
          AND s.state = 'active'
          AND s.capacity_bytes - s.reserved_bytes >= NEW.capacity_bytes
          AND EXISTS (
              SELECT 1
              FROM plue_storage.storage_nodes AS n
              WHERE n.storage_set_id = s.id
                AND n.id = s.active_node_id
                AND n.state = 'active'
                AND n.activation_generation = s.routing_generation
          )
        RETURNING TRUE INTO admitted;
        IF NOT COALESCE(admitted, FALSE) THEN
            RAISE EXCEPTION 'storage set unavailable or capacity exhausted'
                USING ERRCODE = '53100';
        END IF;

        -- The storage-set UPDATE above is the first lock in this trigger. Lock
        -- its selected node in the same order used by routing/drain updates,
        -- then recheck every ownership predicate. If an offline transition won
        -- the race, this statement observes it and the transaction rolls back
        -- the capacity increment.
        PERFORM 1
        FROM plue_storage.storage_nodes AS n
        JOIN plue_storage.storage_sets AS s ON s.id = n.storage_set_id
        WHERE s.id = NEW.storage_set_id
          AND s.state = 'active'
          AND n.id = s.active_node_id
          AND n.state = 'active'
          AND n.activation_generation = s.routing_generation
        FOR SHARE OF n;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'storage node changed during capacity admission'
                USING ERRCODE = '53100';
        END IF;
    END IF;
    RETURN NULL;
END;
$$;
-- END cluster/migrations/0003_harden_placement_locking.sql

-- BEGIN cluster/migrations/0004_runner_fair_admission.sql
-- Keep the per-repository runner admission check independent of task history.
CREATE INDEX IF NOT EXISTS idx_workflow_tasks_active_repo
    ON workflow_tasks (repository_id)
    WHERE status IN ('assigned', 'running');

-- Lock the run before checking its task state. Each statement in this
-- VOLATILE function takes a fresh READ COMMITTED snapshot, including after a
-- competing claim releases the run lock. The marker and claim share that lock.
CREATE OR REPLACE FUNCTION runner_queue_timeout_admissible(
    candidate_run_id bigint,
    candidate_repository_id bigint
) RETURNS boolean LANGUAGE plpgsql VOLATILE AS $$
DECLARE
    expired boolean;
BEGIN
    PERFORM 1 FROM workflow_runs wr
    WHERE wr.id = candidate_run_id
      AND wr.repository_id = candidate_repository_id
      AND wr.execution_plane = 'runner'
      AND wr.status IN ('queued', 'running')
    FOR UPDATE OF wr;
    IF NOT FOUND THEN
        RETURN false;
    END IF;
    SELECT EXISTS (
        SELECT 1 FROM workflow_tasks wt
        WHERE wt.workflow_run_id = candidate_run_id
          AND wt.status = 'pending'
          AND wt.available_at <= NOW() - INTERVAL '120 seconds'
    ) AND NOT EXISTS (
        SELECT 1 FROM workflow_tasks wt
        WHERE wt.workflow_run_id = candidate_run_id
          AND wt.status IN ('assigned', 'running')
    ) INTO expired;
    RETURN expired;
END;
$$;

-- VOLATILE SQL inside PL/pgSQL takes a fresh READ COMMITTED snapshot after
-- ClaimRunnerWorkflowTask wins its nonblocking advisory transaction gate.
-- Counting inline in the claim statement would reuse its old snapshot and
-- let concurrent claimers overfill the reserved slot.
CREATE OR REPLACE FUNCTION runner_claim_admissible(
    candidate_repository_id bigint,
    candidate_manual boolean,
    gate_acquired boolean
) RETURNS boolean LANGUAGE plpgsql VOLATILE AS $$
DECLARE
    repository_active bigint;
    background_active bigint;
BEGIN
    IF NOT gate_acquired THEN
        RETURN false;
    END IF;
    SELECT COUNT(*) INTO repository_active
    FROM workflow_tasks active
    JOIN workflow_runs active_run ON active_run.id = active.workflow_run_id
    WHERE active.repository_id = candidate_repository_id
      AND active.status IN ('assigned', 'running')
      AND active_run.execution_plane = 'runner';
    IF repository_active >= 3 THEN
        RETURN false;
    END IF;
    IF candidate_manual THEN
        RETURN true;
    END IF;
    SELECT COUNT(*) INTO background_active
    FROM workflow_tasks active
    JOIN workflow_runs active_run ON active_run.id = active.workflow_run_id
    WHERE active.status IN ('assigned', 'running')
      AND active_run.execution_plane = 'runner'
      AND active_run.trigger_event NOT IN ('manual_dispatch', 'workflow_dispatch');
    RETURN background_active < 3;
END;
$$;
-- END cluster/migrations/0004_runner_fair_admission.sql

-- BEGIN cluster/migrations/0005_durable_release_tokens.sql
-- Provisioning aborts reuse the reservation token, but deleting a repository
-- much later has its own durable product-journal token. Persist the token that
-- actually released capacity so an ambiguous release commit can be adopted
-- only by the exact operation that performed it.
ALTER TABLE plue_storage.repository_placements
    ADD COLUMN release_token TEXT;

-- Rows released by the earlier migration could only have been released with
-- their reservation token. Preserve that exact idempotency identity before
-- requiring every tombstone to carry one. The table lock taken by ALTER TABLE
-- keeps writers out while the old immutable-tombstone trigger is disabled;
-- both trigger state and data update roll back together on any failure.
ALTER TABLE plue_storage.repository_placements
    DISABLE TRIGGER repository_placements_validate_lifecycle;
UPDATE plue_storage.repository_placements
SET release_token = reservation_token
WHERE state = 'released';
ALTER TABLE plue_storage.repository_placements
    ENABLE TRIGGER repository_placements_validate_lifecycle;

ALTER TABLE plue_storage.repository_placements
    ADD CONSTRAINT repository_placements_release_token_valid
    CHECK (release_token IS NULL OR length(release_token) BETWEEN 16 AND 256),
    ADD CONSTRAINT repository_placements_release_token_lifecycle
    CHECK ((state = 'released') = (release_token IS NOT NULL));

CREATE UNIQUE INDEX repository_placements_release_token_idx
    ON plue_storage.repository_placements(release_token)
    WHERE release_token IS NOT NULL;

CREATE OR REPLACE FUNCTION plue_storage.validate_repository_placement_lifecycle()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'repository placement records are durable and cannot be deleted'
            USING ERRCODE = '55000';
    END IF;

    IF TG_OP = 'INSERT' THEN
        IF NEW.state <> 'reserved' OR NEW.placement_generation <> 1
           OR NEW.release_token IS NOT NULL THEN
            RAISE EXCEPTION 'repository placement must begin reserved at generation 1'
                USING ERRCODE = '55000';
        END IF;
        NEW.created_at = now();
        NEW.updated_at = NEW.created_at;
        NEW.published_at = NULL;
        NEW.released_at = NULL;
        RETURN NEW;
    END IF;

    IF NEW.repository_id <> OLD.repository_id
       OR NEW.reservation_token <> OLD.reservation_token
       OR NEW.capacity_bytes <> OLD.capacity_bytes THEN
        RAISE EXCEPTION 'repository placement identity and capacity are immutable'
            USING ERRCODE = '55000';
    END IF;
    IF OLD.state = 'released' THEN
        IF NEW IS DISTINCT FROM OLD THEN
            RAISE EXCEPTION 'released repository placement cannot be changed'
                USING ERRCODE = '55000';
        END IF;
        RETURN OLD;
    END IF;
    IF OLD.state = 'reserved' AND NEW.state NOT IN ('reserved', 'published', 'released') THEN
        RAISE EXCEPTION 'invalid repository placement transition'
            USING ERRCODE = '55000';
    END IF;
    IF OLD.state = 'published' AND NEW.state NOT IN ('published', 'released') THEN
        RAISE EXCEPTION 'published repository placement cannot return to reserved'
            USING ERRCODE = '55000';
    END IF;
    IF NEW.storage_set_id IS DISTINCT FROM OLD.storage_set_id THEN
        IF OLD.state <> 'published' OR NEW.state <> 'published'
           OR NEW.placement_generation <> OLD.placement_generation + 1 THEN
            RAISE EXCEPTION 'repository relocation requires one higher published generation'
                USING ERRCODE = '55000';
        END IF;
    ELSIF NEW.placement_generation <> OLD.placement_generation THEN
        RAISE EXCEPTION 'placement generation changes only during relocation'
            USING ERRCODE = '55000';
    END IF;

    IF NEW.state = 'released' THEN
        IF NEW.release_token IS NULL THEN
            RAISE EXCEPTION 'repository placement release requires an operation token'
                USING ERRCODE = '55000';
        END IF;
    ELSIF NEW.release_token IS NOT NULL THEN
        RAISE EXCEPTION 'repository placement release token is tombstone-only'
            USING ERRCODE = '55000';
    END IF;

    IF OLD.state = 'reserved' AND NEW.state = 'published' THEN
        NEW.published_at = COALESCE(NEW.published_at, now());
    ELSE
        NEW.published_at = OLD.published_at;
    END IF;
    IF NEW.state = 'released' AND OLD.state <> 'released' THEN
        NEW.released_at = COALESCE(NEW.released_at, now());
    ELSE
        NEW.released_at = OLD.released_at;
    END IF;
    NEW.created_at = OLD.created_at;
    NEW.updated_at = now();
    RETURN NEW;
END;
$$;
-- END cluster/migrations/0005_durable_release_tokens.sql

-- BEGIN cluster/migrations/0006_coding_turn_reconciliation.sql
-- Keep the original session binding across later turns and process restarts.
CREATE TABLE workflow_run_coding_reconciliations (
    workflow_run_id BIGINT PRIMARY KEY REFERENCES workflow_runs(id) ON DELETE CASCADE,
    session_id UUID NOT NULL REFERENCES agent_sessions(id) ON DELETE CASCADE,
    workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
    run_request JSONB CHECK (run_request IS NULL OR COALESCE(jsonb_typeof(run_request) = 'object' AND run_request->>'_tag' = 'Plan' AND run_request->>'planId' <> '' AND run_request->>'digest' <> '' AND jsonb_typeof(run_request->'envelope') = 'object' AND run_request->>'idempotencyKey' = 'agent-turn:' || workflow_run_id || ':run', FALSE)),
    attempted_at TIMESTAMPTZ,
    lease_owner TEXT NOT NULL DEFAULT '',
    lease_expires_at TIMESTAMPTZ,
    next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    cancel_acknowledged_at TIMESTAMPTZ,
    reconciled_at TIMESTAMPTZ
);
CREATE INDEX idx_workflow_run_coding_reconciliations_pending
    ON workflow_run_coding_reconciliations (next_attempt_at, workflow_run_id)
    WHERE reconciled_at IS NULL;
INSERT INTO workflow_run_coding_reconciliations (workflow_run_id, session_id, workspace_id)
SELECT host.workflow_run_id, session.id, host.workspace_id
FROM workflow_run_coding_hosts host
JOIN agent_sessions session ON session.workflow_run_id = host.workflow_run_id;

CREATE FUNCTION register_coding_turn_reconciliation() RETURNS TRIGGER AS $$
BEGIN
    -- Admission already retained the original session, even if a newer turn
    -- has since replaced the session's current workflow binding.
    IF EXISTS (SELECT 1 FROM workflow_run_coding_reconciliations
               WHERE workflow_run_id = NEW.workflow_run_id AND workspace_id = NEW.workspace_id) THEN
        RETURN NEW;
    END IF;
    INSERT INTO workflow_run_coding_reconciliations (workflow_run_id, session_id, workspace_id)
    SELECT NEW.workflow_run_id, id, NEW.workspace_id FROM agent_sessions WHERE workflow_run_id = NEW.workflow_run_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'coding host requires an owning session' USING ERRCODE = 'foreign_key_violation';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_coding_turn_reconciliation
    AFTER INSERT ON workflow_run_coding_hosts
    FOR EACH ROW EXECUTE FUNCTION register_coding_turn_reconciliation();
-- END cluster/migrations/0006_coding_turn_reconciliation.sql
